insert into public.recetas (id, hogar_id, titulo, origen, url_origen, foto_url, tiempo_min, raciones, pasos, paleta, momentos, proteina, capricho, especial, antes) values
('bb88b90d-3ac2-48d9-b1c0-8e6a790656ad','__HOGAR__','Cocido madrileño','importada','https://www.directoalpaladar.com/recetas-de-legumbres-y-verduras/receta-de-cocido-madrileno','https://i.blogs.es/9d92e5/cocido/840_560.jpg',210,2,'[{"texto":"Escurre y lava **los garbanzos** que dejaste en remojo.","min":null,"ingredientes":["garbanzos-secos"]},{"texto":"Pon en una olla grande con agua fría **el morcillo, la gallina, el tocino y los huesos** con una cucharada de sal. Cuando hierva, quita la espuma.","min":10,"ingredientes":["morcillo","pollo-troceado","tocino","huesos-caldo","sal"]},{"texto":"Echa **los garbanzos** con el agua hirviendo y cuece tapado a fuego suave, añadiendo agua caliente si hace falta.","min":150,"ingredientes":["garbanzos-secos"]},{"texto":"Mientras, cuece aparte **el chorizo y la morcilla** (así no engrasan el caldo) y, en otro cazo, **el repollo** troceado.","min":30,"ingredientes":["chorizo","morcilla","repollo"]},{"texto":"Cuando falte media hora, añade al cocido **las patatas y las zanahorias** peladas.","min":30,"ingredientes":["patata","zanahoria"]},{"texto":"Rehoga **el repollo** escurrido con el aceite y el ajo laminado.","min":3,"ingredientes":["aceite-oliva","ajo"]},{"texto":"Cuela **el caldo**, llévalo a ebullición y cuece los fideos para la sopa.","min":3,"ingredientes":["fideos"]},{"texto":"Sirve **por vuelcos**: primero la sopa; luego garbanzos, verduras y repollo; y al final las carnes, el chorizo y la morcilla.","min":null,"ingredientes":[]}]'::jsonb,'{"base":"#D9A85B","d1":"#B5452F","d2":"#6E9B3B","bg":"#F6EAD2"}'::jsonb,array['comida']::text[],'legumbre',false,true,array['La noche antes, pon los garbanzos en remojo en agua fría con un puñado de sal gorda (12 horas).','Pide en la carnicería el morcillo, el tocino y los huesos de caña y espinazo.','Son unas 3 horas de puchero a fuego lento (25 minutos con olla exprés): empieza a media mañana.']::text[]),
('14bf4421-54a1-4e8a-aa3a-a1ee1bfda635','__HOGAR__','Fabada asturiana','importada','https://www.directoalpaladar.com/recetas-de-legumbres-y-verduras/receta-de-fabada-asturiana-al-estilo-tradicional','https://i.blogs.es/979555/fabada_aumentada/840_560.jpg',180,2,'[{"texto":"Escurre **las fabes** y ponlas en una cazuela ancha con la cebolla entera pelada, el ajo, el laurel y el aceite.","min":null,"ingredientes":["fabes","cebolla","ajo","laurel","aceite-oliva"]},{"texto":"Añade **el compango** (chorizo, morcilla y tocino) y cubre con agua fría dos dedos por encima.","min":null,"ingredientes":["chorizo","morcilla","tocino"]},{"texto":"Lleva a ebullición y **«asusta» las fabes**: echa un chorrito de agua fría para cortar el hervor. Repítelo dos veces más durante la cocción.","min":10,"ingredientes":[]},{"texto":"Cuece **a fuego muy suave**, sin remover (mueve la cazuela por las asas) y quitando la espuma. Si se queda seca, añade un poco de agua caliente.","min":180,"ingredientes":[]},{"texto":"A media cocción, añade **el azafrán**. Prueba y sala solo al final, cuando las fabes estén tiernas.","min":null,"ingredientes":["azafran","sal"]},{"texto":"Trocea **el compango** en una fuente y sirve las fabes bien calientes. Si la quieres más espesa, tritura la cebolla con un poco de caldo y devuélvela a la cazuela.","min":null,"ingredientes":[]}]'::jsonb,'{"base":"#E8D9B5","d1":"#B5452F","d2":"#5A2E2A","bg":"#F2EEDD"}'::jsonb,array['comida']::text[],'legumbre',false,true,array['La noche antes, pon las fabes en remojo en un recipiente grande con agua fría: crecen mucho.','Busca fabes de La Granja y el compango (chorizo, morcilla y tocino asturianos).','Son unas 3 horas a fuego muy suave y no se remueve: solo se mueve la cazuela por las asas.']::text[]),
('00d96ec0-7eda-4d91-a294-1cc3e64466d7','__HOGAR__','Falafel casero con pita y salsa de yogur','importada','https://www.directoalpaladar.com/recetas-vegetarianas/como-hacer-falafel-casero-receta-facil-y-deliciosa','https://i.blogs.es/0731dc/falafel/840_560.jpg',60,2,'[{"texto":"Escurre y seca muy bien **los garbanzos remojados** (crudos).","min":null,"ingredientes":["garbanzos-secos"]},{"texto":"Tritúralos con **la cebolla, 1 ajo, el cilantro, el perejil y el comino** hasta tener una pasta granulosa.","min":null,"ingredientes":["cebolla","ajo","cilantro","perejil","comino"]},{"texto":"Añade **la harina** (guarda un par de cucharadas), la levadura, sal y pimienta, y tritura otra vez.","min":null,"ingredientes":["harina","levadura-quimica","sal","pimienta"]},{"texto":"Deja **reposar la masa** en la nevera.","min":30,"ingredientes":[]},{"texto":"Mientras, haz **la salsa**: el yogur con medio pepino rallado y escurrido, el otro ajo picado y sal.","min":null,"ingredientes":["yogur-griego","pepino"]},{"texto":"Forma **bolitas del tamaño de una nuez**, pásalas por la harina reservada y fríelas en aceite caliente hasta que se doren. Escúrrelas en papel.","min":4,"ingredientes":["aceite-oliva"]},{"texto":"Calienta **los panes de pita** y sirve el falafel con la salsa, tomate y lechuga.","min":null,"ingredientes":["pan-pita","tomate","lechuga"]}]'::jsonb,'{"base":"#B07A3B","d1":"#6E9B3B","d2":"#F2E8D5","bg":"#F2EEDD"}'::jsonb,array['comida','cena']::text[],'legumbre',false,true,array['Un día antes, pon los garbanzos SECOS en remojo 24 horas (los de bote no sirven: el falafel se deshace).','La masa reposa 30 minutos en la nevera antes de formar las bolitas.']::text[]),
('1da28af3-a51c-4f7a-9b0f-84986e6a5dea','__HOGAR__','Carrilleras al vino tinto con puré de patata','importada','https://www.directoalpaladar.com/recetas-de-carnes-y-aves/carrilleras-cerdo-al-vino-tinto-receta-para-impresionar-e-impresionarte','https://i.blogs.es/20529a/carrilleras/840_560.jpg',135,2,'[{"texto":"Limpia **las carrilleras** de telillas, salpimiéntalas y pásalas por harina, sacudiendo el exceso.","min":null,"ingredientes":["carrilleras-cerdo","sal","pimienta","harina"]},{"texto":"Márcalas en una cazuela con el aceite **a fuego fuerte** hasta que se doren por todos los lados. Resérvalas.","min":6,"ingredientes":["aceite-oliva"]},{"texto":"En la misma cazuela, pocha **la cebolla, el ajo, los pimientos y la zanahoria** picados.","min":10,"ingredientes":["cebolla","ajo","pimiento-rojo","pimiento-verde","zanahoria"]},{"texto":"Echa **el vino tinto** y deja que reduzca a fuego fuerte para que se vaya el alcohol.","min":5,"ingredientes":["vino-tinto"]},{"texto":"Vuelve a poner las carrilleras, cubre con **el caldo**, tapa y cuece a fuego suave hasta que estén muy tiernas (20 minutos en olla exprés).","min":105,"ingredientes":["caldo-carne"]},{"texto":"Mientras, cuece **las patatas** peladas y cháfalas con la leche caliente, la mantequilla, sal y nuez moscada.","min":25,"ingredientes":["patata","leche","mantequilla","nuez-moscada"]},{"texto":"Saca la carne, **tritura la salsa** y cuélala. Si está líquida, hiérvela unos minutos y sírvela por encima, con el puré.","min":5,"ingredientes":[]}]'::jsonb,'{"base":"#6B2E2A","d1":"#E9C46A","d2":"#F2E8D5","bg":"#F3E1D6"}'::jsonb,array['comida']::text[],'carne',false,true,array['Pide en la carnicería las carrilleras limpias, sin hueso ni grasa.','Son 1 h 45 min a fuego suave (20 minutos con olla exprés): empieza con tiempo.']::text[]),
('fd9c5c55-60c3-4fae-ab65-1d4e432460ea','__HOGAR__','Canelones de pollo y champiñones gratinados','importada','https://www.directoalpaladar.com/recetas-de-pasta/mejor-receta-canelones-pollo-facil-truco-rapido-queden-perfectos','https://i.blogs.es/23b70b/canelones_de_pollo/840_560.jpeg',90,2,'[{"texto":"Cuece **la pechuga** en agua con sal (o usa pollo asado) y desmenúzala.","min":15,"ingredientes":["pechuga-pollo","sal"]},{"texto":"Haz **la bechamel**: cocina la harina con la mantequilla 5 minutos y añade la leche y la nata en tres veces, removiendo hasta que espese.","min":10,"ingredientes":["harina","mantequilla","leche","nata"]},{"texto":"Pocha **la cebolla** picada con el aceite y añade los champiñones picados a fuego medio-alto.","min":15,"ingredientes":["cebolla","aceite-oliva","champinones"]},{"texto":"El truco: añade **el pollo, la soja y 4 cucharadas de bechamel** y cocina todo junto para que el relleno quede meloso. Salpimienta y deja enfriar.","min":7,"ingredientes":["salsa-soja","pimienta"]},{"texto":"Hidrata **las placas**, pon relleno en un extremo y enróllalas.","min":null,"ingredientes":["placas-canelones"]},{"texto":"Pon una capa fina de bechamel en la fuente, coloca los canelones, cúbrelos con **el resto de la bechamel y el queso** y gratina a 225 °C hasta que se doren.","min":15,"ingredientes":["queso-rallado"]}]'::jsonb,'{"base":"#F2E8D5","d1":"#E9C46A","d2":"#C98B54","bg":"#F6EFD9"}'::jsonb,array['comida','cena']::text[],'carne',false,true,array['El relleno tiene que enfriarse antes de rellenar: si quieres, déjalo hecho la noche antes.','Mira en el paquete cuánto tiempo hay que hidratar las placas.']::text[]),
('e08a723f-bfc7-48a5-9936-1e3ba99e1042','__HOGAR__','Pollo tikka masala con arroz basmati','importada','https://www.directoalpaladar.com/recetas-de-carnes-y-aves/pollo-tikka-masala-receta-pollo-especiado-popular-mundo','https://i.blogs.es/304df0/pollo_tikka_masala/840_560.jpg',50,2,'[{"texto":"Mezcla **las especias** con el jengibre rallado y reparte la mezcla en dos: una mitad para el adobo y otra para la salsa.","min":null,"ingredientes":["garam-masala","comino","curcuma","jengibre"]},{"texto":"Corta **el pollo** en trozos, mézclalo con el yogur, la mitad de las especias y sal, y déjalo en la nevera.","min":120,"ingredientes":["contramuslos-pollo","yogur-natural","sal"]},{"texto":"Tritura **la cebolla, los tomates, el ajo y el tomate concentrado** con el resto de especias y pimienta.","min":null,"ingredientes":["cebolla","tomate","ajo","tomate-concentrado","pimienta"]},{"texto":"Dora **el pollo** escurrido en una sartén con el aceite a fuego fuerte.","min":8,"ingredientes":["aceite-oliva"]},{"texto":"Añade **la salsa triturada y la leche de coco** y cuece a fuego medio hasta que el pollo esté hecho y la salsa espese.","min":20,"ingredientes":["leche-coco"]},{"texto":"Mientras, cuece **el arroz basmati**.","min":12,"ingredientes":["arroz-basmati"]},{"texto":"Sirve con **cilantro fresco** picado por encima.","min":null,"ingredientes":["cilantro"]}]'::jsonb,'{"base":"#D9692E","d1":"#F2E8D5","d2":"#4E7A33","bg":"#F6E3DC"}'::jsonb,array['comida','cena']::text[],'carne',false,true,array['La noche antes (o al menos 2 horas antes), deja el pollo en adobo de yogur y especias en la nevera.']::text[]),
('f93d87e2-c59c-4532-a157-5dab445ee5fc','__HOGAR__','Musaka griega','importada','https://www.directoalpaladar.com/recetas-de-carnes-y-aves/moussaka-receta-griega','https://i.blogs.es/011c57/musaka/840_560.jpg',90,2,'[{"texto":"Corta **la berenjena** en rodajas, sálalas y déjalas sobre papel absorbente.","min":30,"ingredientes":["berenjena","sal"]},{"texto":"Sécalas y fríelas ligeramente con un poco de aceite, igual que **la patata** en rodajas finas. Resérvalas.","min":10,"ingredientes":["aceite-oliva","patata"]},{"texto":"Pocha **la cebolla y la zanahoria** muy picadas; añade los tomates picados y cocina hasta tener un sofrito espeso.","min":15,"ingredientes":["cebolla","zanahoria","tomate"]},{"texto":"Dora **la carne**, júntala con el sofrito, el tomillo, la canela, el vino y el caldo, y cuece hasta que no quede líquido.","min":10,"ingredientes":["picada-ternera","tomillo","canela","vino-tinto","caldo-carne","pimienta"]},{"texto":"Haz **la bechamel** con la mantequilla, la harina y la leche, con una pizca de nuez moscada.","min":8,"ingredientes":["mantequilla","harina","leche","nuez-moscada"]},{"texto":"Monta por capas: **patata, berenjena, carne, berenjena y carne**, apretando un poco con una cuchara.","min":null,"ingredientes":[]},{"texto":"Cubre con **la bechamel y el parmesano**, hornea a 160 °C y gratina 3 minutos a 220 °C.","min":20,"ingredientes":["parmesano"]}]'::jsonb,'{"base":"#C98B54","d1":"#5B3A5E","d2":"#F2E8D5","bg":"#F2EADB"}'::jsonb,array['comida','cena']::text[],'carne',false,true,array['Sala las rodajas de berenjena 30 minutos antes para que suelten el agua y el amargor.','Se monta por capas, como una lasaña: ten a mano una fuente de horno.']::text[]),
('6b17bf48-90c9-4acc-94c4-2169fbb25258','__HOGAR__','Empanada de pollo y setas con masa casera','importada','https://www.directoalpaladar.com/recetas-de-aperitivos/empanada-casera-pollo-setas-receta-sencilla-socorrida-cuando-somos-muchos-a-comer','https://i.blogs.es/ff59f9/empanada_pollo/840_560.jpg',90,2,'[{"texto":"Corta **el pollo** en dados, salpimiéntalo y saltéalo con un poco de aceite hasta que cambie de color. Resérvalo.","min":5,"ingredientes":["pechuga-pollo","pimienta"]},{"texto":"En el mismo aceite, pocha **la cebolla** picada y añade las setas troceadas hasta que suelten el agua y se doren.","min":12,"ingredientes":["cebolla","setas"]},{"texto":"Vuelve a poner el pollo, añade **una cucharada de harina y la nata** y remueve hasta que ligue. Ajusta de sal y deja enfriar.","min":3,"ingredientes":["nata"]},{"texto":"Para **la masa**: mezcla 200 g de harina con una pizca de sal, 50 ml de aceite tibio y 70 ml de agua, y amasa 2 minutos hasta que esté lisa. Déjala reposar tapada.","min":30,"ingredientes":["harina","aceite-oliva","sal"]},{"texto":"Divide la masa en dos, estira **dos láminas finas**, pon el relleno frío sobre una y tápalo con la otra, sellando bien los bordes. Haz un agujerito en el centro.","min":null,"ingredientes":[]},{"texto":"Pinta con **el huevo batido** y hornea a 190 °C hasta que esté dorada. Déjala templar sobre una rejilla.","min":30,"ingredientes":["huevos"]},{"texto":"Sirve con **una ensalada** de lechuga y tomate.","min":null,"ingredientes":["lechuga","tomate"]}]'::jsonb,'{"base":"#D9A23F","d1":"#F2E8D5","d2":"#8C6A4F","bg":"#F6EAD2"}'::jsonb,array['comida','cena']::text[],'carne',false,true,array['El relleno tiene que estar frío antes de cerrar la empanada: hazlo lo primero (o la noche antes).','Si vas justo de tiempo, puedes usar 2 láminas de masa de empanada compradas.']::text[]),
('a0893770-b167-4a97-a8ad-f135b72779b1','__HOGAR__','Arroz al horno','importada','https://www.directoalpaladar.com/recetas-de-arroces/receta-tradicional-de-arroz-al-horno','https://i.blogs.es/f01715/arroz_horno/840_560.jpg',60,2,'[{"texto":"Precalienta el horno a **220 °C** y pon a calentar el caldo.","min":null,"ingredientes":["caldo-carne"]},{"texto":"Dora en la cazuela con el aceite **la patata en rodajas** y resérvala.","min":5,"ingredientes":["aceite-oliva","patata"]},{"texto":"Dora **la costilla** salada y, al final, la morcilla en trozos grandes, solo un minuto.","min":8,"ingredientes":["costilla-cerdo","morcilla","sal"]},{"texto":"Añade **el arroz y los garbanzos** escurridos con el pimentón y rehoga un minuto.","min":1,"ingredientes":["arroz-redondo","garbanzos-cocidos","pimenton"]},{"texto":"Coloca encima las patatas, **la cabeza de ajos** en el centro y el tomate partido por la mitad. Vierte el caldo caliente con el azafrán.","min":null,"ingredientes":["ajo","tomate","azafran"]},{"texto":"Hornea **sin tocarlo** hasta que el arroz se seque.","min":20,"ingredientes":[]},{"texto":"Deja **reposar tapado** con un paño unos minutos antes de servir.","min":5,"ingredientes":[]}]'::jsonb,'{"base":"#C98B3B","d1":"#5A2E2A","d2":"#E9C46A","bg":"#F6EAD2"}'::jsonb,array['comida']::text[],'carne',false,true,array['Necesitas una cazuela de barro o una fuente honda que vaya al horno.','Si hacéis cocido, guardad su caldo (se puede congelar): es el mejor para este arroz.']::text[]),
('81468fb8-92dc-478c-812e-b29885835395','__HOGAR__','Lasaña de verduras','importada','https://www.directoalpaladar.com/recetas-de-pasta/verduras-sabrosas-deliciosas-para-hacer-mejor-lasana-vegetariana-receta-video-incluido','https://i.blogs.es/e2509f/lasana_verduras/840_560.jpg',75,2,'[{"texto":"Saltea **los champiñones** troceados con un poco de aceite, salpimienta, añade las espinacas y tapa: se hacen con el calor.","min":5,"ingredientes":["champinones","aceite-oliva","espinacas","sal","pimienta"]},{"texto":"Rehoga a fuego suave **la zanahoria en dados y el brócoli picado** hasta que estén al dente.","min":8,"ingredientes":["zanahoria","brocoli"]},{"texto":"Rehoga **la cebolla picada y la berenjena en dados** hasta que estén muy tiernas.","min":12,"ingredientes":["cebolla","berenjena"]},{"texto":"Haz **la bechamel** con la mantequilla, la harina y la leche, con una pizca de nuez moscada.","min":8,"ingredientes":["mantequilla","harina","leche","nuez-moscada"]},{"texto":"Monta en una fuente **capas de pasta, verduras, tomate y bechamel**, y termina con bechamel y parmesano.","min":null,"ingredientes":["laminas-lasana","tomate-triturado","parmesano"]},{"texto":"Hornea a **200 °C** hasta que se dore por encima.","min":20,"ingredientes":[]}]'::jsonb,'{"base":"#E8D9B5","d1":"#4E7A33","d2":"#E9843B","bg":"#EEF1E4"}'::jsonb,array['comida','cena']::text[],'lacteo',false,true,array['Son tres rellenos de verdura por separado: ten todo cortado antes de empezar.','Si las láminas no son precocidas, cuécelas antes según el paquete.']::text[]),
('f91e1d14-a343-44a2-a6d5-84828708c951','__HOGAR__','Quiche de verduras con masa casera','importada','https://www.directoalpaladar.com/recetas-de-huevos-y-tortillas/quiche-de-verduras','https://i.blogs.es/5f612c/quiche_vegetariano/840_560.jpg',105,2,'[{"texto":"Para **la masa**: frota la mantequilla fría en dados con la harina y una pizca de sal hasta que no queden trozos. Añade 1 huevo batido (guarda una cucharada), une sin amasar mucho y deja reposar en la nevera.","min":30,"ingredientes":["harina","mantequilla","huevos","sal"]},{"texto":"Rehoga a fuego suave **la cebolleta** con el aceite; cuando esté transparente, añade la zanahoria y, 10 minutos después, el calabacín.","min":20,"ingredientes":["cebolleta","aceite-oliva","zanahoria","calabacin"]},{"texto":"Bate **los 3 huevos con la nata** y salpimienta con poca sal (el queso ya sala).","min":null,"ingredientes":["nata","pimienta"]},{"texto":"Estira la masa, forra el molde, pincha la base y **hornéala en blanco** a 180 °C, cubierta con papel y legumbres para que no suba.","min":20,"ingredientes":[]},{"texto":"Quita el peso y **pinta la base** con el huevo reservado para sellarla.","min":null,"ingredientes":[]},{"texto":"Rellena con las verduras, **el queso y la mezcla de huevo** y hornea a 180 °C hasta que esté dorada.","min":30,"ingredientes":["queso-rallado"]},{"texto":"Deja **reposar 10 minutos** y sirve con una ensalada.","min":10,"ingredientes":["lechuga","tomate"]}]'::jsonb,'{"base":"#F2CF5B","d1":"#6E9B3B","d2":"#E9843B","bg":"#F6EFD9"}'::jsonb,array['comida','cena']::text[],'huevo',false,true,array['La masa reposa 30 minutos en la nevera y se hornea sola 20 minutos antes de rellenarla.','Necesitas un molde de unos 18-20 cm y legumbres secas para hacer peso al hornear la base.']::text[]),
('2d6b6cf7-5764-408f-886d-9aaa798086c0','__HOGAR__','Tajine de pollo con verduras y cuscús','importada','https://www.directoalpaladar.com/recetas-de-carnes-y-aves/receta-de-tajine-de-pollo-y-verduras','https://i.blogs.es/4a4d2c/tajine_pollo/840_560.jpg',60,2,'[{"texto":"Pon **las ciruelas** en remojo en agua templada.","min":30,"ingredientes":["ciruelas-pasas"]},{"texto":"Pica en trozos pequeños **la cebolla, el puerro, la zanahoria, el calabacín y el tomate**.","min":null,"ingredientes":["cebolla","puerro","zanahoria","calabacin","tomate"]},{"texto":"En el tajine o en una cazuela, rehoga las verduras con el aceite a fuego bajo y añade **el pollo** salado.","min":10,"ingredientes":["aceite-oliva","pollo-troceado","sal"]},{"texto":"Cuando el pollo tome color, añade **el ras el hanout, el pimentón y el tomate concentrado** y remueve un minuto.","min":1,"ingredientes":["ras-el-hanout","pimenton","tomate-concentrado"]},{"texto":"Cubre con **el caldo y las ciruelas** escurridas, tapa y cuece a fuego mínimo hasta que el pollo esté tierno y la salsa espesa.","min":30,"ingredientes":["caldo-pollo"]},{"texto":"Mientras, hidrata **el cuscús** con el mismo peso de agua hirviendo con sal y suéltalo con un tenedor.","min":5,"ingredientes":["cuscus"]}]'::jsonb,'{"base":"#C98B3B","d1":"#E9843B","d2":"#4E7A33","bg":"#F6EAD2"}'::jsonb,array['comida','cena']::text[],'carne',false,true,array['Compra ras el hanout (mezcla marroquí de especias): está en la sección de especias o en tiendas de alimentación árabe.','Pon las ciruelas en remojo 30 minutos antes de empezar.']::text[]);

